from __future__ import annotations

import json
import os

from ledgerlock import format as fmt
from ledgerlock import store


class ConflictError(Exception):
    def __init__(self, key=None, incoming_rid=None, committed_rid=None, batch_index=None):
        super().__init__(
            f"conflict on key {key!r}: incoming rid {incoming_rid!r} "
            f"vs committed rid {committed_rid!r}"
        )
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index


class Ledger:
    def __init__(self, path):
        self.path = os.fspath(path)

    def append(self, operation):
        return append(self, operation)

    def verify(self):
        return verify(self)

    def snapshot(self):
        return snapshot(self)

    def apply_batch(self, operations):
        return apply_batch(self, operations)

    def repair_tail(self):
        return repair_tail(self)


def _serialize_line(fields: dict) -> bytes:
    return (
        json.dumps(fields, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode(
            "utf-8"
        )
        + b"\n"
    )


def _read_state(path):
    try:
        raw_lines = store.read_lines(path)
    except FileNotFoundError:
        raw_lines = []
    committed = {}
    tail_hash = fmt.GENESIS
    for raw in raw_lines:
        line = json.loads(raw.decode("utf-8"))
        key = line.get("key")
        if key is not None:
            committed[fmt.normalize_key(key)] = line
        h = line.get("hash")
        if h is not None:
            tail_hash = h
    return raw_lines, committed, tail_hash


def _build_fields(operation):
    op = operation[0]
    if op == "put":
        if len(operation) != 5:
            raise ValueError("put requires (op, key, value, rid, ts)")
        _, raw_key, value, rid, ts = operation
        fields = {"op": "put", "key": None, "value": value, "ts": ts, "id": rid}
    elif op == "delete":
        if len(operation) != 4:
            raise ValueError("delete requires (op, key, rid, ts)")
        _, raw_key, rid, ts = operation
        fields = {"op": "delete", "key": None, "ts": ts, "id": rid}
    else:
        raise ValueError(f"unknown op: {op!r}")

    key = fmt.normalize_key(raw_key)
    if key == "":
        raise ValueError("empty key")
    fields["key"] = key
    return fields, key, rid


def append(ledger, operation):
    fields, key, rid = _build_fields(operation)

    _, committed, tail_hash = _read_state(ledger.path)

    existing = committed.get(key)
    if existing is not None:
        if existing["id"] == rid:
            result = dict(existing)
            result["replayed"] = True
            result["committed"] = False
            return result
        raise ConflictError(
            key=key, incoming_rid=rid, committed_rid=existing["id"], batch_index=None
        )

    fields["prev_hash"] = tail_hash
    fields["hash"] = fmt.line_hash(tail_hash, fields)
    _append_bytes(ledger.path, _serialize_line(fields))
    return fields


def _verify_lines(lines) -> dict:
    if not lines:
        return {"ok": True, "first_bad_index": None}
    prev_hash = None
    for i, raw in enumerate(lines):
        try:
            line = json.loads(raw.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            return {"ok": False, "first_bad_index": i}
        if not isinstance(line, dict):
            return {"ok": False, "first_bad_index": i}
        stored_prev = line.get("prev_hash")
        stored_hash = line.get("hash")
        if not isinstance(stored_prev, str) or not isinstance(stored_hash, str):
            return {"ok": False, "first_bad_index": i}
        if i == 0:
            if stored_prev != fmt.GENESIS:
                return {"ok": False, "first_bad_index": 0}
        elif stored_prev != prev_hash:
            return {"ok": False, "first_bad_index": i}
        if fmt.line_hash(stored_prev, line) != stored_hash:
            return {"ok": False, "first_bad_index": i}
        prev_hash = stored_hash
    return {"ok": True, "first_bad_index": None}


def verify(ledger):
    lines = store.read_lines(ledger.path)
    return _verify_lines(lines)


def snapshot(ledger):
    lines = store.read_lines(ledger.path)
    state = {}
    for raw in lines:
        line = json.loads(raw.decode("utf-8"))
        key = fmt.normalize_key(line["key"])
        if line["op"] == "put":
            state[key] = line["value"]
        elif line["op"] == "delete":
            state.pop(key, None)
    return {k: state[k] for k in sorted(state)}


def apply_batch(ledger, operations):
    ops = list(operations)
    raw_lines, committed, tail_hash = _read_state(ledger.path)
    committed_rids = {k: v["id"] for k, v in committed.items()}

    new_lines = []
    new_fields = []

    for idx, operation in enumerate(ops):
        fields, key, rid = _build_fields(operation)

        committed_rid = committed_rids.get(key)
        if committed_rid is not None:
            if committed_rid == rid:
                continue
            raise ConflictError(
                key=key,
                incoming_rid=rid,
                committed_rid=committed_rid,
                batch_index=idx,
            )

        fields["prev_hash"] = tail_hash
        fields["hash"] = fmt.line_hash(tail_hash, fields)
        new_lines.append(_serialize_line(fields))
        new_fields.append(fields)
        committed_rids[key] = rid
        tail_hash = fields["hash"]

    if new_lines:
        out_lines = [raw + b"\n" for raw in raw_lines] + new_lines
        store.write_atomic(ledger.path, out_lines)
    return new_fields


def repair_tail(ledger):
    path = os.fspath(ledger.path)
    with open(path, "rb") as f:
        data = f.read()

    if data == b"":
        return {"ok": True, "first_bad_index": None}

    raw_lines = data.split(b"\n")
    if raw_lines and raw_lines[-1] == b"":
        raw_lines.pop()

    ends_with_newline = data.endswith(b"\n")
    truncated = not ends_with_newline
    if not truncated and raw_lines:
        try:
            json.loads(raw_lines[-1].decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            truncated = True

    if not truncated:
        return verify(ledger)

    prefix = raw_lines[:-1]
    verdict = _verify_lines(prefix)
    if verdict["ok"]:
        out_lines = [raw + b"\n" for raw in prefix]
        store.write_atomic(path, out_lines)
        return {"ok": True, "first_bad_index": None}
    return verdict


def _tail_hash(path):
    _, _, tail_hash = _read_state(path)
    return tail_hash


def _append_bytes(path, data):
    with open(path, "ab") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())

